import express from 'express';

const app = express();
app.use(express.json());

// 使用内存存储替代 Redis
const leaderboard = new Map();

// API: 更新玩家分数
app.post('/api/score', async (req, res) => {
  const { playerId, score } = req.body;

  if (!playerId || score === undefined) {
    return res.status(400).json({ error: 'Missing playerId or score' });
  }

  const currentScore = leaderboard.get(playerId) || 0;
  if (score > currentScore) {
    leaderboard.set(playerId, score);
    console.log(`✅ Updated ${playerId}: ${score} points`);
  }

  res.json({ success: true, playerId, score });
});

// API: 获取排行榜前100名
app.get('/api/leaderboard', async (req, res) => {
  const sortedPlayers = Array.from(leaderboard.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 100)
    .map(([playerId, score], index) => ({
      rank: index + 1,
      playerId,
      score
    }));

  res.json({ 
    total: leaderboard.size,
    leaderboard: sortedPlayers 
  });
});

app.get('/health', (req, res) => {
  res.json({ status: 'OK', players: leaderboard.size });
});

const PORT = 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
  console.log(`📊 Leaderboard API ready!`);

  // 演示模式：5秒后自动停止
  console.log(`\n⏰ Demo mode: Server will stop in 5 seconds...`);
  setTimeout(() => {
    console.log('\n✅ Demo completed! Server shutting down.');
    server.close(() => {
      console.log('👋 Server stopped.');
      process.exit(0);
    });
  }, 5000);
});

