import assert from 'assert';

console.log('🧪 Running tests...\n');

// 测试 1: Map 基本操作
console.log('Test 1: Map operations');
const testMap = new Map();
testMap.set('player1', 100);
testMap.set('player2', 200);
assert.strictEqual(testMap.get('player1'), 100);
assert.strictEqual(testMap.get('player2'), 200);
console.log('✅ Map operations work\n');

// 测试 2: 排序逻辑
console.log('Test 2: Sorting logic');
const players = [
  ['Alice', 300],
  ['Bob', 500],
  ['Charlie', 200]
];
const sorted = players.sort((a, b) => b[1] - a[1]);
assert.strictEqual(sorted[0][0], 'Bob');
assert.strictEqual(sorted[1][0], 'Alice');
assert.strictEqual(sorted[2][0], 'Charlie');
console.log('✅ Sorting works correctly\n');

// 测试 3: 切片操作
console.log('Test 3: Array slicing');
const top2 = sorted.slice(0, 2);
assert.strictEqual(top2.length, 2);
assert.strictEqual(top2[0][0], 'Bob');
console.log('✅ Array slicing works\n');

// 测试 4: 数据转换
console.log('Test 4: Data transformation');
const formatted = sorted.map(([name, score], index) => ({
  rank: index + 1,
  name,
  score
}));
assert.strictEqual(formatted[0].rank, 1);
assert.strictEqual(formatted[0].name, 'Bob');
assert.strictEqual(formatted[0].score, 500);
console.log('✅ Data transformation works\n');

console.log('🎉 All tests passed!');
console.log('Total: 4/4 tests ✅');
